{"implementation": "def solve(case):
    payload = case.get("payload")
    if payload is None:
        raise ValueError("Missing 'payload' in case")
    nodes = payload.get("nodes")
    required_symbols = payload.get("required_symbols")
    if nodes is None:
        raise ValueError("Missing 'nodes' in payload")
    if required_symbols is None:
        raise ValueError("Missing 'required_symbols' in payload")
    if not isinstance(nodes, list):
        raise ValueError("'nodes' must be a list")
    if not isinstance(required_symbols, list):
        raise ValueError("'required_symbols' must be a list")
    req_sym_set = set(required_symbols)
    required_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    for node in nodes:
        missing = required_fields - set(node.keys())
        if missing:
            raise ValueError(
                f"Node {node.get('id', '?')} missing fields: {missing}"
            )
    node_map = {n["id"]: n for n in nodes}
    if len(node_map) != len(nodes):
        raise ValueError("Duplicate node IDs detected")
    children = {n["id"]: [] for n in nodes}
    for n in nodes:
        if n["parent"] is not None:
            if n["parent"] not in node_map:
                raise ValueError(
                    f"Unknown parent '{n['parent']}' referenced by node '{n['id']}'"
                )
            children[n["parent"]].append(n["id"])
    roots = [n for n in nodes if n["parent"] is None]
    if len(roots) != 1:
        raise ValueError(
            f"Expected exactly one root node, found {len(roots)}"
        )
    retained = set(n["id"] for n in nodes)
    removal_order = []
    # Deeper nodes first; node ID (lexicographic) as stable tiebreaker.
    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))
    def covered_without(excluded_id):
        """True iff every required symbol has at least one representative
        in retained after hypothetically excluding excluded_id."""
        for sym in req_sym_set:
            found = False
            for nid in retained:
                if nid != excluded_id and node_map[nid]["symbol"] == sym:
                    found = True
                    break
            if not found:
                return False
        return True
    for node in candidates:
        nid = node["id"]
        # Already removed in an earlier iteration.
        if nid not in retained:
            continue
        # Hard guard: must be flagged removable.
        if not node["removable"]:
            continue
        # Hard guard: never remove the root.
        if node["parent"] is None:
            continue
        # Hard guard: never remove a node whose symbol is required.
        if node["symbol"] in req_sym_set:
            continue
        # Hard guard: never remove a node that still has retained children.
        if any(child in retained for child in children[nid]):
            continue
        # Tentative check: all required symbols remain covered after removal.
        if covered_without(nid):
            retained.discard(nid)
            removal_order.append(nid)
    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order,
    }
"}
